class Test01_BasicFunctionality(unittest.TestCase):
    def setUp(self):
        self.provisioner = UserSpaceProvisioner(root_dir="/tmp/test_workspaces")

    def test_register_user_success(self):
        """Target: register_user | Input: 'new_user' | Expected: True, user in registry as False"""
        result = self.provisioner.register_user("new_user")
        self.assertTrue(result)
        self.assertIn("new_user", self.provisioner.registry)
        self.assertFalse(self.provisioner.registry["new_user"])

    def test_register_user_duplicate(self):
        """Target: register_user | Input: 'existing_user' twice | Expected: False on second attempt"""
        self.provisioner.register_user("existing_user")
        result = self.provisioner.register_user("existing_user")
        self.assertFalse(result)

    def test_get_pending_deployments(self):
        """Target: get_pending_deployments | Input: Two registered users | Expected: List containing both usernames"""
        self.provisioner.register_user("user_a")
        self.provisioner.register_user("user_b")
        pending = self.provisioner.get_pending_deployments()
        self.assertIn("user_a", pending)
        self.assertIn("user_b", pending)
        self.assertEqual(len(pending), 2)

