import datetime
from typing import Any, Dict, List

class AuthenticatedMarketSimulator:
    def __init__(self):
        # A directory of registered users where keys are usernames and values indicate active session status
        self._participant_registry: Dict[str, bool] = {}
        # A repository of mock economic data streams
        self._scenario_data: Dict[str, Any] = {}
        # An immutable audit trail recording successful data access events
        self._compliance_ledger: List[Dict[str, Any]] = []

    def register_participant(self, username: str) -> bool:
        """
        Enrolls a new user in the simulation environment with an initial offline status.
        Returns True if registration was successful; False if the username is already taken.
        """
        if username in self._participant_registry:
            return False
        self._participant_registry[username] = False
        return True

    def authenticate_session(self, username: str) -> bool:
        """
        Activates a user's session, granting them permission to request data streams.
        Returns True if the user exists and the session is activated; False otherwise.
        """
        if username not in self._participant_registry:
            return False
        self._participant_registry[username] = True
        return True

    def load_simulation_data(self, indicator_key: str, data_points: List[float]) -> None:
        """
        Injects specific mock data into the simulation environment.
        """
        self._scenario_data[indicator_key] = data_points

    def secure_fetch_data(self, username: str, indicator_key: str) -> Dict[str, Any]:
        """
        Retrieves mock data for a specific indicator only if the requesting user is currently authenticated.
        Automatically logs the access event to the compliance ledger.
        """
        # Check if user exists
        if username not in self._participant_registry:
            return {"status": "denied", "reason": "User not registered"}

        # Check if user is authenticated
        if not self._participant_registry[username]:
            return {"status": "denied", "reason": "User not signed in"}

        # Retrieve data (returns None if key doesn't exist)
        data = self._scenario_data.get(indicator_key)

        # Log the successful access event
        log_entry = {
            "user": username,
            "key": indicator_key,
            "timestamp": datetime.datetime.now().isoformat()
        }
        self._compliance_ledger.append(log_entry)

        return {"status": "success", "data": data}

    def get_active_session_audit(self) -> List[Dict[str, Any]]:
        """
        Retrieves audit logs specifically for users who are currently signed in.
        """
        return [
            entry for entry in self._compliance_ledger
            if self._participant_registry.get(entry["user"]) is True
        ]

    def validate_full_participation(self) -> bool:
        """
        Checks if all registered participants are currently authenticated.
        Returns True if every registered user is signed in (or if registry is empty).
        """
        return all(self._participant_registry.values())

