import unittest

class Test01_BasicFunctionality(unittest.TestCase):
    def test_generate_signature_strong_celsius(self):
        """Target: generate_signature | Input: {'weather': 'sunny', 'temperature': 25.0, 'units': 'celsius'}, as_weak=False | Expected: "sunny-25.0C" (exact float, quotes included)"""
        ctrl = MeteorologicalCacheController("Tokyo")
        data = {'weather': 'sunny', 'temperature': 25.0, 'units': 'celsius'}
        # Expecting exact float formatting and double quotes as per ETag standard and examples
        expected = '"sunny-25.0C"'
        self.assertEqual(ctrl.generate_signature(data, as_weak=False), expected)

    def test_generate_signature_weak_fahrenheit_conversion(self):
        """Target: generate_signature | Input: {'weather': 'cloudy', 'temperature': 77, 'units': 'fahrenheit'}, as_weak=True | Expected: W/"cloudy-25C" (rounded, converted to C)"""
        ctrl = MeteorologicalCacheController("Tokyo")
        # 77F = 25C exactly
        data = {'weather': 'cloudy', 'temperature': 77, 'units': 'fahrenheit'}
        expected = 'W/"cloudy-25C"'
        self.assertEqual(ctrl.generate_signature(data, as_weak=True), expected)

class Test02_Initialization(unittest.TestCase):
    def test_init_defaults(self):
        """Target: __init__ | Input: city="London" | Expected: Defaults set (tolerance=0.5, universal_match=False, empty sets)"""
        ctrl = MeteorologicalCacheController("London")
        self.assertEqual(ctrl.monitored_city, "London")
        self.assertEqual(ctrl.temp_tolerance, 0.5)
        self.assertFalse(ctrl.universal_match)
        self.assertIsInstance(ctrl.valid_signatures, frozenset)
        self.assertIsInstance(ctrl.approximate_signatures, frozenset)

    def test_init_custom_configuration(self):
        """Target: __init__ | Input: universal_match=True, tolerance=1.5, signatures provided | Expected: Fields reflect input"""
        strong = ['"test-1"']
        weak = ['W/"test-2"']
        ctrl = MeteorologicalCacheController("Paris", strong_signatures=strong, weak_signatures=weak, universal_match=True, tolerance=1.5)
        self.assertTrue(ctrl.universal_match)
        self.assertEqual(ctrl.temp_tolerance, 1.5)
        self.assertIn('"test-1"', ctrl.valid_signatures)
        self.assertIn('W/"test-2"', ctrl.approximate_signatures)

