        """Target: register_snapshot | Input: data, is_strong=True | Expected: Signature added to valid_signatures"""
        ctrl = MeteorologicalCacheController("Berlin")
        data = {'weather': 'rain', 'temperature': 10.0, 'units': 'celsius'}
        ctrl.register_snapshot(data, is_strong=True)
        self.assertIn('"rain-10.0C"', ctrl.valid_signatures)

