        ctrl = MeteorologicalCacheController("Berlin")
        data = {'weather': 'mist', 'temperature': 10.0, 'units': 'celsius'}
        ctrl.register_snapshot(data, is_strong=False)
        self.assertIn('W/"mist-10C"', ctrl.approximate_signatures)

    def test_get_header_representation_standard(self):
        """Target: get_header_representation | Input: Registered tags | Expected: Comma-separated string of tags"""
        ctrl = MeteorologicalCacheController("Rome")
        ctrl.valid_signatures = {'"strong-1"'}
        ctrl.approximate_signatures = {'W/"weak-1"'}
        header = ctrl.get_header_representation()
        self.assertIn('"strong-1"', header)
        self.assertIn('W/"weak-1"', header)
        self.assertIn(',', header)

