        data = {'weather': 'sun', 'temperature': 20, 'units': 'celsius'}
        self.assertFalse(ctrl.validate_live_condition(data))

class Test10_IntegrationBehavior(unittest.TestCase):
    def test_validate_live_condition_strong_exact_match(self):
        """Target: validate_live_condition | Input: Registered strong, exact match data | Expected: True"""
        ctrl = MeteorologicalCacheController("Madrid")
        data = {'weather': 'clear', 'temperature': 30.0, 'units': 'celsius'}
        ctrl.register_snapshot(data, is_strong=True)
        self.assertTrue(ctrl.validate_live_condition(data, require_strong=True))

    def test_validate_live_condition_weak_match_via_rounding(self):
        """Target: validate_live_condition | Input: Registered weak (15.0), live data (15.4) | Expected: True (both round to 15)"""
        ctrl = MeteorologicalCacheController("Madrid")
        # Registering 15.0 creates weak tag W/"cloudy-15C"
        reg_data = {'weather': 'cloudy', 'temperature': 15.0, 'units': 'celsius'}
        ctrl.register_snapshot(reg_data, is_strong=False)

        # Validating 15.4 creates weak tag W/"cloudy-15C" (rounds down)
        live_data = {'weather': 'cloudy', 'temperature': 15.4, 'units': 'celsius'}
        self.assertTrue(ctrl.validate_live_condition(live_data, require_strong=False))

    def test_validate_live_condition_universal_bypass(self):
        """Target: validate_live_condition | Input: universal_match=True, unregistered data | Expected: True"""
        ctrl = MeteorologicalCacheController("Global", universal_match=True)
        data = {'weather': 'snow', 'temperature': -50.0, 'units': 'celsius'}
        self.assertTrue(ctrl.validate_live_condition(data))

