import socket

class NetSemanticTokenizer:
    def __init__(self, resolve_ips=True, base_vocab=None):
        """
        Initializes the tokenizer with a base vocabulary and network configuration.
        """
        self._resolve_ips = resolve_ips
        self._special_tokens = ["<pad>", "<unk>", "<bos>", "<eos>", "<mask>"]
        self._dns_cache = {}

        # Initialize Vocab
        if base_vocab:
            self._vocab = base_vocab.copy()
        else:
            self._vocab = {token: i for i, token in enumerate(self._special_tokens)}

        self._ids_to_tokens = {v: k for k, v in self._vocab.items()}
        self._base_vocab_size = len(self._vocab)

    def vocab_size(self):
        """Returns current vocabulary size."""
        return len(self._vocab)

    def pad_token_id(self):
        """Returns ID for <pad>."""
        return self._vocab.get("<pad>")

    def eos_token_id(self):
        """Returns ID for <eos>."""
        return self._vocab.get("<eos>")

    def all_special_ids(self):
        """Returns list of IDs for special tokens."""
        return [self._vocab[t] for t in self._special_tokens if t in self._vocab]

    def all_special_tokens(self):
        """Returns list of special token strings."""
        return self._special_tokens

    def is_fast(self):
        """Compatibility marker."""
        return False

    def _is_valid_ipv4(self, ip_address):
        """Internal helper to validate IPv4 format."""
        try:
            socket.inet_pton(socket.AF_INET, ip_address)
            return True
        except socket.error:
            return False

    def _is_valid_ipv6(self, ip_address):
        """Internal helper to validate IPv6 format."""
        try:
            socket.inet_pton(socket.AF_INET6, ip_address)
            return True
        except socket.error:
            return False

    def _resolve_and_register(self, ip_address):
        """
        Performs a reverse DNS lookup for an IP. 
        Updates cache and vocabulary if a new hostname is found.
        """
        # Check cache first
        if ip_address in self._dns_cache:
            hostname = self._dns_cache[ip_address]
        else:
            try:
                # Network dependency
                hostname, _, _ = socket.gethostbyaddr(ip_address)
                self._dns_cache[ip_address] = hostname
            except socket.error:
                hostname = ip_address # Fallback to IP if resolution fails
                self._dns_cache[ip_address] = hostname # Cache failure to avoid retry

        # Tokenizer state dependency: Add new hostname to vocab if it's new
        if hostname not in self._vocab:
            new_id = len(self._vocab)
            self._vocab[hostname] = new_id
            self._ids_to_tokens[new_id] = hostname

        return hostname

    def get_added_vocab(self):
        """Returns only the tokens added dynamically via network resolution."""
        return {k: v for k, v in self._vocab.items() if v >= self._base_vocab_size}

    def encode(self, text):
        """
        Tokenizes text with network awareness. 
        Identifies IPs, resolves them, and updates vocabulary dynamically.
        """
        if isinstance(text, list):
            # Handle batch encoding recursively
            return [self.encode(t) for t in text]

        # Simple whitespace tokenization
        raw_tokens = text.split()
        token_ids = []

        for token in raw_tokens:
            final_token = token

            # Cross-domain logic: If enabled, check network format
            if self._resolve_ips:
                if self._is_valid_ipv4(token) or self._is_valid_ipv6(token):
                    # Mutates vocab state during encoding
                    final_token = self._resolve_and_register(token)

            # Map to ID
            if final_token in self._vocab:
                token_ids.append(self._vocab[final_token])
            else:
                # Handle unknown words by adding them to ensure reversibility
                new_id = len(self._vocab)
                self._vocab[final_token] = new_id
                self._ids_to_tokens[new_id] = final_token
                token_ids.append(new_id)

        return token_ids

    def decode(self, token_ids, skip_special_tokens=False, **kwargs):
        """Converts IDs back to text."""
        if isinstance(token_ids, int):
            token_ids = [token_ids]

        decoded_tokens = []
        for tid in token_ids:
            if tid in self._ids_to_tokens:
                token = self._ids_to_tokens[tid]
                if skip_special_tokens and token in self._special_tokens:
                    continue
                decoded_tokens.append(token)

        return " ".join(decoded_tokens)

from typing import Any, List, Set, Dict

class AuthGuardedContainer:
    def __init__(self):
        self._secure_value: Any = None
        self._required_access_tags: Set[str] = set()
        self._user_registry: Dict[str, bool] = {}
        # Tracks if the container has been written to at least once
        self._is_empty: bool = True

    def register_user(self, username: str) -> bool:
        if username in self._user_registry:
            return False
        self._user_registry[username] = False
        return True

    def authenticate_user(self, username: str) -> bool:
        if username not in self._user_registry:
            return False
        self._user_registry[username] = True
        return True

    def store_secure_content(self, value: Any, required_tags: List[str]) -> bool:
        new_tags = set(required_tags)
        signed_in_users = {u for u, signed_in in self._user_registry.items() if signed_in}

        # Authorization Logic:
        # 1. Allow if container is empty (fresh write).
        # 2. Allow if at least one currently signed-in user is present in the NEW required tags (chain of custody).
        if self._is_empty or not signed_in_users.isdisjoint(new_tags):
            self._secure_value = value
            self._required_access_tags = new_tags
            self._is_empty = False
            return True

        return False

    def retrieve_content(self) -> Any:
        if self.check_access_status():
            return self._secure_value
        return None

    def check_access_status(self) -> bool:
        signed_in_users = {u for u, signed_in in self._user_registry.items() if signed_in}
        # Access is granted if currently signed-in users are a superset of required tags
        return self._required_access_tags.issubset(signed_in_users)

    def get_missing_authorizers(self) -> List[str]:
        signed_in_users = {u for u, signed_in in self._user_registry.items() if signed_in}
        # Identify tags that are required but not currently signed in
        missing = self._required_access_tags - signed_in_users
        return sorted(list(missing))

    def is_fully_locked_out(self) -> bool:
        signed_in_users = {u for u, signed_in in self._user_registry.items() if signed_in}
        # True if there is absolutely no overlap between signed-in users and required tags
        return self._required_access_tags.isdisjoint(signed_in_users)

import re

class LexicalGraphProvider:
    def __init__(self):
        self._vocabulary = set()
        self._context_tokens = []
        self._token_map = {}

    def ingest_vocabulary(self, word_list):
        """
        Populates the internal registry with valid words.
        """
        self._vocabulary.update(word_list)

    def set_context(self, sentence):
        """
        Sanitizes the input sentence, splits it into tokens, and builds an internal index map.
        """
        # Remove punctuation using regex
        cleaned_sentence = re.sub(r'[^\w\s]', '', sentence)

        # Split into tokens
        self._context_tokens = cleaned_sentence.split()

        # Build token map for quick lookup (token -> index)
        # Note: If duplicates exist, this maps to the last occurrence.
        self._token_map = {token: i for i, token in enumerate(self._context_tokens)}

        return len(self._context_tokens)

    def identify(self, requirement_or_candidate):
        """
        Normalizes a requirement or candidate into a hashable identifier.
        """
        return requirement_or_candidate.strip().lower()

    def get_preference(self, identifier, resolutions, candidates, information, backtrack_causes):
        """
        Calculates the resolution priority based on word length (Longest Word logic).
        Returns negated length to sort longer words first.
        """
        return -len(identifier)

    def find_matches(self, identifier, requirements, incompatibilities):
        """
        Locates candidates that exist in BOTH the global _vocabulary and the current _context_tokens.
        """
        context_set = set(self._context_tokens)

        for candidate in self._vocabulary:
            # Check if candidate is incompatible
            if candidate in incompatibilities:
                continue

            # Check if candidate exists in the current context and matches the identifier
            if candidate in context_set and self.is_satisfied_by(identifier, candidate):
                yield candidate

    def is_satisfied_by(self, requirement, candidate):
        """
        Validates if a candidate word lexically matches the requirement (case-insensitive).
        """
        return requirement.lower() == candidate.lower()

    def get_dependencies(self, candidate):
        """
        Establishes a dependency chain based on sentence structure.
        Returns the word immediately preceding the candidate in the context.
        """
        index = self._token_map.get(candidate)

        # If candidate not found or is the first word (no predecessor)
        if index is None or index == 0:
            return []

        # Return the predecessor
        return [self._context_tokens[index - 1]]

class HypertextJobMarket:
    _codes = {
        200: "OK",
        201: "Created",
        204: "No Content",
        400: "Bad Request",
        404: "Not Found",
        409: "Conflict",
        500: "Internal Server Error"
    }

    def __init__(self):
        self.job_listings = []
        self.resumes = []
        self.last_status = 200
        self.last_phrase = self._codes[200]

    def _set_state(self, code):
        self.last_status = code
        self.last_phrase = self._codes.get(code, "Unknown")
        return code

    def post_job(self, job_title, company, requirements):
        if not job_title or not company or not requirements:
            return self._set_state(400)

        job = {
            "title": job_title,
            "company": company,
            "requirements": requirements
        }
        self.job_listings.append(job)
        return self._set_state(201)

    def remove_job(self, job):
        if job in self.job_listings:
            self.job_listings.remove(job)
            return self._set_state(200)
        return self._set_state(404)

    def submit_resume(self, name, skills, experience):
        if not name or not skills or not experience:
            return self._set_state(400)

        for resume in self.resumes:
            if resume['name'] == name:
                return self._set_state(409)

        new_resume = {
            "name": name,
            "skills": skills,
            "experience": experience
        }
        self.resumes.append(new_resume)
        return self._set_state(201)

    def withdraw_resume(self, resume):
        if resume in self.resumes:
            self.resumes.remove(resume)
            return self._set_state(200)
        return self._set_state(404)

    def search_jobs(self, criteria):
        matches = []
        for job in self.job_listings:
            if criteria in job['requirements']:
                matches.append(job)

        if matches:
            self._set_state(200)
        else:
            self._set_state(404)
        return matches

    def get_job_applicants(self, job):
        if job not in self.job_listings:
            self._set_state(404)
            return []

        matches = []
        job_reqs = set(job['requirements'])

        for resume in self.resumes:
            resume_skills = set(resume['skills'])
            # Candidate matches if they possess all required skills
            if job_reqs.issubset(resume_skills):
                matches.append(resume)

        if matches:
            self._set_state(200)
        else:
            self._set_state(204)

        return matches

    def get_reason_phrase(self, value=None):
        if value is None:
            return self.last_phrase
        return self._codes.get(value, "Unknown")

    def is_success(self, value=None):
        status = value if value is not None else self.last_status
        return 200 <= status < 300

    def is_client_error(self, value=None):
        status = value if value is not None else self.last_status
        return 400 <= status < 500

    def is_server_error(self, value=None):
        status = value if value is not None else self.last_status
        return 500 <= status < 600

class HttpCommerceSession:
    def __init__(self, payment_threshold=1000.0):
        """
        Initializes the empty inventory, defines the HTTP status code map, 
        and sets the initial state to 200 OK.
        """
        self._inventory = {}
        self._payment_threshold = payment_threshold
        self._current_status_code = 200
        self._reason_phrases = {
            200: "OK",
            201: "Created",
            204: "No Content",
            400: "Bad Request",
            402: "Payment Required",
            404: "Not Found",
            409: "Conflict",
            500: "Internal Server Error"
        }

    def request_add_item(self, item_name, price, quantity=1):
        """
        Attempts to add an item to the inventory. 
        Validates input to potentially trigger 400 Bad Request. 
        If the item is new, triggers 201 Created; if updating an existing item, triggers 200 OK.
        """
        if price < 0 or quantity <= 0:
            return self._set_state(400)

        if item_name in self._inventory:
            self._inventory[item_name]['quantity'] += quantity
            self._inventory[item_name]['price'] = price
            return self._set_state(200)
        else:
            self._inventory[item_name] = {'price': price, 'quantity': quantity}
            return self._set_state(201)

    def request_remove_item(self, item_name, quantity=1):
        """
        Attempts to remove items. 
        Triggers 404 Not Found if the item doesn't exist, 
        409 Conflict if trying to remove more than available, 
        204 No Content if the item is fully depleted/removed, 
        or 200 OK for partial decrement.
        """
        if item_name not in self._inventory:
            return self._set_state(404)

        current_quantity = self._inventory[item_name]['quantity']

        if quantity > current_quantity:
            return self._set_state(409)
        elif quantity == current_quantity:
            del self._inventory[item_name]
            return self._set_state(204)
        else:
            self._inventory[item_name]['quantity'] -= quantity
            return self._set_state(200)

    def get_inventory_snapshot(self):
        """
        Retrieves the current inventory state. 
        Automatically sets the internal status to 200 OK (successful retrieval).
        """
        self._set_state(200)
        return self._inventory

    def calculate_checkout_total(self):
        """
        Calculates the total cost. 
        If the cart is empty, sets status to 204 No Content. 
        If the total exceeds _payment_threshold, sets status to 402 Payment Required. 
        Otherwise, sets 200 OK.
        """
        if not self._inventory:
            self._set_state(204)
            return 0.0

        total = sum(item['price'] * item['quantity'] for item in self._inventory.values())

        if total > self._payment_threshold:
            self._set_state(402)
        else:
            self._set_state(200)

        return total

    def get_current_phrase(self):
        """
        Returns the human-readable reason phrase corresponding to the _current_status_code.
        """
        return self._reason_phrases.get(self._current_status_code, "Unknown Status")

    def is_success(self):
        """
        Checks if the most recent operation resulted in a success state (2xx).
        """
        return 200 <= self._current_status_code < 300

    def is_client_error(self):
        """
        Checks if the most recent operation resulted in a client error (4xx).
        """
        return 400 <= self._current_status_code < 500

    def _set_state(self, code):
        """
        Internal helper to update the _current_status_code.
        """
        self._current_status_code = code
        return code

import copy

class HierarchicalPersonToken(tuple):
    def __new__(cls, *args, **kwargs):
        # Tuple accepts only the iterable path arguments
        return super().__new__(cls, args)

    def __init__(self, *args, name=None, sex=None, phoneNumber=None, parent=None):
        # 1. Initialize Tree Structure
        self.subtypes = set()
        self.parent = parent

        # 2. Initialize and Validate Person Data
        # We handle the possibility that 'name' etc are passed as kwargs
        self.name = self._validate_name(name)
        self.sex = self._validate_sex(sex)
        self.phoneNumber = self._validate_phoneNumber(phoneNumber)

    # --- Validation Domain Methods ---

    def _validate_name(self, name):
        if not isinstance(name, str) or not name or len(name) > 33:
            return None
        return name

    def _validate_sex(self, sex):
        if sex not in ["Man", "Woman", "UGM"]:
            return None
        return sex

    def _validate_phoneNumber(self, phoneNumber):
        if not isinstance(phoneNumber, str) or not phoneNumber.isdigit() or len(phoneNumber) != 11:
            return None
        return phoneNumber

    # --- Token/Hierarchy Domain Methods ---

    def __getattr__(self, key):
        # Factory Logic: Create child node if key is Uppercase
        if key and key[0].isupper():
            # Construct new tuple path
            new_args = self + (key,)
            # Create child, propagating current person data
            child = HierarchicalPersonToken(
                *new_args,
                name=self.name,
                sex=self.sex,
                phoneNumber=self.phoneNumber,
                parent=self
            )
            self.subtypes.add(child)
            return child
        raise AttributeError(f"'{type(self).__name__}' object has no attribute '{key}'")

    def split(self):
        result = []
        curr = self
        while curr:
            result.append(curr)
            curr = curr.parent
        return list(reversed(result))

    def __contains__(self, val):
        if self == val:
            return True
        for subtype in self.subtypes:
            if val in subtype:
                return True
        return False

    def __repr__(self):
        path_str = ".".join(str(x) for x in self)
        # Summary of data validity
        valid_status = "Valid" if (self.name and self.sex and self.phoneNumber) else "Invalid/Incomplete"
        data_summary = f"[{self.name}, {self.sex}]"
        return f"<{self.__class__.__name__}: {path_str} {data_summary} ({valid_status})>"

    def __copy__(self):
        return self

    def __deepcopy__(self, memo):
        return self

