import datetime
import copy
from typing import List, Dict, Optional

class MacroSimulationScheduler:
    """
    This class integrates economic data mocking with temporal resource scheduling to manage a timeline 
    of "market simulation windows." It allows users to define specific time slots where distinct 
    economic scenarios are active, ensuring no two simulations overlap in time while providing 
    an audit trail of all data access and scheduling events.
    """

    def __init__(self, scheduler_id: int):
        self.scheduler_id = scheduler_id
        self._scenario_registry: Dict[str, dict] = {}
        self._scheduled_windows: List[dict] = []
        self._execution_log: List[dict] = []

    def load_default_scenarios(self) -> None:
        """
        Populates the scenario registry with hardcoded historical mock data (e.g., SP500, VIX) 
        to bootstrap the system.
        """
        self._scenario_registry = {
            'baseline_growth': {
                'SP500': 4500.50,
                'VIX': 14.2,
                'Inflation': 2.5,
                'Unemployment': 3.8
            },
            'recession_2008': {
                'SP500': 2800.00,
                'VIX': 45.5,
                'Inflation': 0.1,
                'Unemployment': 8.5
            },
            'high_inflation': {
                'SP500': 3900.25,
                'VIX': 22.0,
                'Inflation': 8.9,
                'Unemployment': 4.1
            },
            'market_crash': {
                'SP500': 3200.00,
                'VIX': 60.0,
                'Inflation': 1.5,
                'Unemployment': 5.0
            }
        }
        self._log_interaction("load_default_scenarios", {"scenarios_count": len(self._scenario_registry)})

    def schedule_execution_window(self, scenario_key: str, start_time: str, end_time: str) -> bool:
        """
        Attempts to book a specific economic scenario into a time slot. 
        It validates that the scenario exists in the registry AND that the time slot 
        does not conflict with existing windows.
        """
        # Check if scenario exists
        if scenario_key not in self._scenario_registry:
            self._log_interaction("schedule_failure", {
                "reason": "missing_scenario_key", 
                "key": scenario_key
            })
            return False

        # Check for conflicts
        if self._check_window_conflict(start_time, end_time):
            self._log_interaction("schedule_conflict", {
                "start": start_time, 
                "end": end_time, 
                "cause": "overlap"
            })
            return False

        # Schedule the window
        self._scheduled_windows.append({
            'scenario_key': scenario_key,
            'start_time': start_time,
            'end_time': end_time
        })

        self._log_interaction("schedule_success", {
            "scenario_key": scenario_key, 
            "start": start_time, 
            "end": end_time
        })
        return True

    def get_market_data_at(self, query_time: str) -> Optional[dict]:
        """
        Retrieves the economic indicators active at a specific time. 
        It searches the schedule for a window covering query_time, then fetches 
        the corresponding data from the registry.
        """
        query_min = self._time_to_minutes(query_time)

        for window in self._scheduled_windows:
            start_min = self._time_to_minutes(window['start_time'])
            end_min = self._time_to_minutes(window['end_time'])

            # Check if query time is within the window [start, end]
            if start_min <= query_min <= end_min:
                data = self._scenario_registry.get(window['scenario_key'])
                self._log_interaction("data_retrieval", {
                    "time": query_time, 
                    "found": True, 
                    "scenario": window['scenario_key']
                })
                return data

        self._log_interaction("data_retrieval", {
            "time": query_time, 
            "found": False
        })
        return None

    def _check_window_conflict(self, new_start: str, new_end: str) -> bool:
        """
        Internal helper that compares a proposed time range against all currently scheduled windows 
        to detect overlaps. Enforces strict boundary checks (end time of A == start time of B is a conflict).
        """
        ns = self._time_to_minutes(new_start)
        ne = self._time_to_minutes(new_end)

        for window in self._scheduled_windows:
            ws = self._time_to_minutes(window['start_time'])
            we = self._time_to_minutes(window['end_time'])

            # Strict overlap check: max(start_A, start_B) <= min(end_A, end_B)
            # This logic ensures that if one ends at 10:00 and another starts at 10:00,
            # max(10:00, 10:00) <= min(10:00, 10:00) is True, flagging a conflict.
            if max(ns, ws) <= min(ne, we):
                return True

        return False

    def _log_interaction(self, action: str, details: dict) -> None:
        """
        Records internal system events with a timestamp to the _execution_log.
        """
        entry = {
            'timestamp': datetime.datetime.now().isoformat(),
            'action': action,
            'details': details
        }
        self._execution_log.append(entry)

    def get_audit_trail(self) -> List[dict]:
        """
        Returns a safe copy of the execution log to review how the simulation schedule was built and accessed.
        """
        return copy.deepcopy(self._execution_log)

    @staticmethod
    def _time_to_minutes(t: str) -> int:
        """Helper to convert HH:MM string to minutes since midnight."""
        h, m = map(int, t.split(':'))
        return h * 60 + m

class HierarchicalTimeNode(tuple):
    def __new__(cls, node_name, parent=None):
        # Create tuple path: (parent_path..., node_name)
        if parent:
            path = parent + (node_name,)
        else:
            path = (node_name,)
        return super(HierarchicalTimeNode, cls).__new__(cls, path)

    def __init__(self, node_name, parent=None):
        # Prevent re-initialization if retrieved from cache/copy
        if hasattr(self, '_timeline'):
            return

        self._node_name = node_name
        self._parent = parent
        self._subtypes = set()
        self._timeline = [] # List of dicts: {'name', 'start', 'end'}

    def __getattr__(self, name):
        # Dynamic factory for child nodes
        if name[0].isupper():
            # Check if we already have this subtype to maintain singleton-like behavior within tree
            for child in self._subtypes:
                if child._node_name == name:
                    return child

            # Create new child coupled to this parent
            new_node = HierarchicalTimeNode(name, parent=self)
            self._subtypes.add(new_node)
            return new_node
        raise AttributeError(f"'{type(self).__name__}' object has no attribute '{name}'")

    def _parse_time(self, time_str):
        # Converts 'HH:MM' to minutes from midnight
        h, m = map(int, time_str.split(':'))
        return h * 60 + m

    def _detect_conflict(self, new_start, new_end):
        # Checks local timeline for overlaps
        for event in self._timeline:
            evt_start = self._parse_time(event['start_time'])
            evt_end = self._parse_time(event['end_time'])

            # Conflict logic: Overlap including boundaries (Strict)
            # (StartA <= EndB) and (EndA >= StartB)
            if (new_start <= evt_end) and (new_end >= evt_start):
                return True
        return False

    def _check_hierarchy_conflict(self, new_start, new_end):
        # Recursive step: Check if parent is booked
        if self._parent:
            if self._parent._detect_conflict(new_start, new_end):
                return True
            return self._parent._check_hierarchy_conflict(new_start, new_end)
        return False

    def book_time_slot(self, event_details):
        start_min = self._parse_time(event_details['start_time'])
        end_min = self._parse_time(event_details['end_time'])

        # 1. Check Local Conflicts
        if self._detect_conflict(start_min, end_min):
            return False

        # 2. Check Ancestor Conflicts (The Hybrid Logic)
        if self._check_hierarchy_conflict(start_min, end_min):
            return False

        # 3. Add to schedule
        self._timeline.append(event_details)
        return True

    def is_available(self, check_time):
        t_min = self._parse_time(check_time)
        # Check specific point in time against local and hierarchy
        # We treat a point check as a 0-duration interval for conflict detection
        is_blocked_locally = self._detect_conflict(t_min, t_min)
        is_blocked_parent = self._check_hierarchy_conflict(t_min, t_min)

        return not (is_blocked_locally or is_blocked_parent)

    def get_lineage(self):
        # Reconstruction of the Token path
        if self._parent:
            return self._parent.get_lineage() + [self]
        return [self]

    def __repr__(self):
        return ".".join([n._node_name for n in self.get_lineage()])

