import os
import random
from typing import Any, Dict, List, Union

class OperationalHazardGrid:
    """
    This class fuses environment-based configuration management with a grid-based hazard simulation.
    It represents the system's operational state as a spatial grid where the dimensions and hazard density
    are defined by infrastructure settings (pool size and overflow limits).
    """

    def __init__(self):
        """
        Initializes the provider, captures the environment, and automatically generates the hazard grids
        based on infrastructure settings.
        """
        self._env = os.environ
        self._cache: Dict[str, Any] = {}
        self._grid_dimension: int = 0
        self._hazard_count: int = 0
        self._hazard_map: List[List[Union[str, int]]] = []
        self._system_view: List[List[str]] = []
        self._failures_detected: int = 0

        # Initialize the simulation state
        self.reload_simulation()

    def get_database_url(self) -> str:
        """Retrieves the database URL from the environment."""
        return self._env.get("DATABASE_URL", "sqlite:///maverick_mcp.db")

    def get_redis_config(self) -> Dict[str, Any]:
        """Aggregates all Redis-related settings into a single dictionary for connectivity."""
        return {
            "host": self._env.get("REDIS_HOST", "localhost"),
            "port": int(self._env.get("REDIS_PORT", 6379)),
            "db": int(self._env.get("REDIS_DB", 0)),
            "password": self._env.get("REDIS_PASSWORD", None),
            "ssl": self._env.get("REDIS_SSL", "False").lower() == "true"
        }

    def get_pool_size(self) -> int:
        """Retrieves the DB pool size, which also defines the grid dimension (N)."""
        return int(self._env.get("POOL_SIZE", 5))

    def get_max_overflow(self) -> int:
        """Retrieves the max overflow setting, which also defines the total hazard count (K)."""
        return int(self._env.get("MAX_OVERFLOW", 10))

    def get_max_retries(self) -> int:
        """Retrieves the allowed retries, which acts as the 'Lives' counter for the simulation."""
        return int(self._env.get("MAX_RETRIES", 3))

    def is_production_mode(self) -> bool:
        """Checks if running in production; determines if hazard sweeping is 'hardcore'."""
        return self._env.get("ENVIRONMENT", "").lower() == "production"

    def get_log_level(self) -> str:
        """Retrieves logging level; affects how sweep results are reported."""
        return self._env.get("LOG_LEVEL", "INFO")

    def get_fred_api_key(self) -> str:
        """Retrieves the FRED API key."""
        return self._env.get("FRED_API_KEY", "")

    def get_tiingo_api_key(self) -> str:
        """Retrieves the Tiingo API key."""
        return self._env.get("TIINGO_API_KEY", "")

    def generate_hazard_map(self) -> List[List[Union[str, int]]]:
        """
        Internal method to generate the hidden grid ('X' for hazards). 
        Uses get_pool_size() for dimensions and get_max_overflow() for density.
        """
        dim = self._grid_dimension
        count = self._hazard_count

        # Initialize grid with 0s
        grid = [[0 for _ in range(dim)] for _ in range(dim)]

        # Determine actual number of mines (cap at grid size)
        total_cells = dim * dim
        num_mines = min(count, total_cells)

        # Randomly place mines
        if total_cells > 0:
            mine_indices = random.sample(range(total_cells), num_mines)
            for idx in mine_indices:
                r, c = divmod(idx, dim)
                grid[r][c] = 'X'

        # Calculate proximity counts
        for r in range(dim):
            for c in range(dim):
                if grid[r][c] == 'X':
                    continue

                mines_nearby = 0
                # Check all 8 neighbors
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < dim and 0 <= nc < dim:
                            if grid[nr][nc] == 'X':
                                mines_nearby += 1
                grid[r][c] = mines_nearby

        return grid

    def generate_system_view(self) -> List[List[str]]:
        """Resets the operator's view of the grid to all unknown ('-')."""
        dim = self._grid_dimension
        return [['-' for _ in range(dim)] for _ in range(dim)]

    def verify_sector(self, x: int, y: int) -> Dict[str, Any]:
        """
        The primary logic method ('sweep'). Probes a sector of the grid.
        """
        # Boundary check
        if not (0 <= x < self._grid_dimension and 0 <= y < self._grid_dimension):
            return {
                "status": "INVALID_COORDINATES",
                "view": self._system_view,
                "failures": self._failures_detected
            }

        cell_content = self._hazard_map[x][y]

        if cell_content == 'X':
            self._failures_detected += 1

            # Determine failure severity
            if self.is_production_mode():
                status = "CRITICAL_FAILURE"
            elif self._failures_detected > self.get_max_retries():
                status = "SYSTEM_LOCKDOWN"
            else:
                status = "HAZARD_DETECTED"

            return {
                "status": status,
                "view": self._system_view,
                "failures": self._failures_detected
            }
        else:
            # Safe move: Reveal the sector
            self._system_view[x][y] = cell_content

            # Cache the successful move
            self._cache[f"sector_verified_{x}_{y}"] = True

            return {
                "status": "SAFE",
                "view": self._system_view,
                "failures": self._failures_detected
            }

    def check_system_integrity(self) -> bool:
        """Checks if the 'game' is won (all non-hazard tiles revealed)."""
        for r in range(self._grid_dimension):
            for c in range(self._grid_dimension):
                # If it's not a hazard, it must be revealed (not '-') to win
                if self._hazard_map[r][c] != 'X' and self._system_view[r][c] == '-':
                    return False
        return True

    def get_config_value(self, key: str, default: Any) -> Any:
        """Generic configuration getter that utilizes the internal _cache."""
        return self._cache.get(key, default)

    def set_config_value(self, key: str, value: Any) -> None:
        """Sets a value in the internal cache."""
        self._cache[key] = value

    def reload_simulation(self) -> None:
        """
        Clears the cache and regenerates the hazard grids based on current 
        environment variables (effectively restarting the game).
        """
        self._cache.clear()
        self._grid_dimension = self.get_pool_size()
        self._hazard_count = self.get_max_overflow()
        self._failures_detected = 0
        self._hazard_map = self.generate_hazard_map()
        self._system_view = self.generate_system_view()

import warnings

class GomokuVersionState:
    def __init__(self, vstring="10.0.88"):
        warnings.warn("distutils Version classes are deprecated. Use packaging.version instead.", DeprecationWarning)
        self.board = []
        self.winner = None
        self.board_size = 0
        self.move_count = 0
        self.current_player = 'X'
        self.version_string = ""
        self.parse(vstring)

    def parse(self, vstring):
        """Parses 'Major.Minor.Patch' -> 'Size.MoveCount.PlayerASCII'."""
        try:
            # Handle potential build metadata (e.g., "+winnerX")
            base_ver = vstring.split('+')[0]
            parts = [int(x) for x in base_ver.split('.')]

            self.board_size = parts[0]
            self.move_count = parts[1]
            # Convert Patch number back to char (88->'X', 79->'O')
            self.current_player = chr(parts[2])

            # Initialize board if empty (Note: This simple parser resets the board 
            # layout because the version string doesn't store stone positions, 
            # only the game configuration and progress count).
            if not self.board:
                self.board = [[' ' for _ in range(self.board_size)] for _ in range(self.board_size)]

            self.version_string = vstring
        except (ValueError, IndexError):
            raise ValueError(f"Invalid version format '{vstring}'. Expected 'Size.Moves.PlayerASCII'")

    def _update_version_string(self):
        """Regenerates the version string based on internal game state."""
        patch = ord(self.current_player)
        base = f"{self.board_size}.{self.move_count}.{patch}"
        if self.winner:
            self.version_string = f"{base}+winner{self.winner}"
        else:
            self.version_string = base

    def make_move(self, row, col):
        """Places stone, increments version (move count), toggles player."""
        if self.winner:
            return False # Game is in a finalized version state

        if 0 <= row < self.board_size and 0 <= col < self.board_size:
            if self.board[row][col] == ' ':
                # 1. Update Game State
                self.board[row][col] = self.current_player

                # 2. Check Victory (Updates self.winner)
                self.check_winner()

                # 3. Update Version State
                if not self.winner:
                    # Toggle player only if game continues
                    self.current_player = 'O' if self.current_player == 'X' else 'X'

                self.move_count += 1

                # 4. Sync State to String
                self._update_version_string()
                return True
        return False

    def check_winner(self):
        """Scans board for 5-in-a-row."""
        for r in range(self.board_size):
            for c in range(self.board_size):
                if self.board[r][c] != ' ':
                    # Check all 4 directions
                    directions = [(0, 1), (1, 0), (1, 1), (1, -1)]
                    for d in directions:
                        if self._check_five_in_a_row(r, c, d):
                            self.winner = self.board[r][c]
                            return self.winner
        return None

    def _check_five_in_a_row(self, row, col, direction):
        dr, dc = direction
        symbol = self.board[row][col]
        for i in range(1, 5):
            nr, nc = row + dr * i, col + dc * i
            if not (0 <= nr < self.board_size and 0 <= nc < self.board_size):
                return False
            if self.board[nr][nc] != symbol:
                return False
        return True

    def _cmp(self, other):
        """Compares two game states. 
        Returns negative if self < other, 0 if equal, positive if self > other.
        Comparison Hierarchy: Board Size (Major) -> Move Count (Minor).
        """
        if isinstance(other, GomokuVersionState):
            if self.board_size != other.board_size:
                return self.board_size - other.board_size
            if self.move_count != other.move_count:
                return self.move_count - other.move_count
            return 0
        return NotImplemented

    def __repr__(self):
        return f"GomokuVersionState ('{self.version_string}')"

    def __eq__(self, other):
        c = self._cmp(other)
        if c is NotImplemented: return c
        return c == 0

    def __lt__(self, other):
        c = self._cmp(other)
        if c is NotImplemented: return c
        return c < 0

    def __le__(self, other):
        c = self._cmp(other)
        if c is NotImplemented: return c
        return c <= 0

    def __gt__(self, other):
        c = self._cmp(other)
        if c is NotImplemented: return c
        return c > 0

    def __ge__(self, other):
        c = self._cmp(other)
        if c is NotImplemented: return c
        return c >= 0

import os
from typing import Any, Optional, Tuple, List

class StrategicConfigurationEngine:
    """
    Fuses environment configuration management with Gomoku game logic.
    Maps configuration keys to coordinates on a game board.
    """

    # List of keys to scan for in environment variables during init
    # These act as system obstacles ('O') if present.
    KNOWN_KEYS = [
        "DATABASE_URL", "REDIS_HOST", "ENVIRONMENT", "DEBUG", 
        "SECRET_KEY", "API_KEY", "CONFIG_GRID_SIZE", "APP_MODE"
    ]

    def __init__(self, board_size_override: Optional[int] = None):
        self._env = os.environ
        self._cache: dict[str, Any] = {}
        self._integrity_verified = False
        self._key_map: dict[str, Tuple[int, int]] = {}

        # Determine board size
        if board_size_override is not None:
            self._board_size = board_size_override
        else:
            env_size = self._env.get("CONFIG_GRID_SIZE")
            self._board_size = int(env_size) if env_size else 15

        # Initialize board with None
        self._board: List[List[Optional[str]]] = [
            [None for _ in range(self._board_size)] 
            for _ in range(self._board_size)
        ]

        # Pre-populate board with existing environment variables
        for key in self.KNOWN_KEYS:
            if key in self._env:
                self._place_env_obstacle(key)

    def _place_env_obstacle(self, key: str) -> None:
        """Internal helper to place 'O' for existing env vars."""
        r, c = self._map_key_to_coord(key)
        # Only place if the spot is empty
        if self._board[r][c] is None:
            self._board[r][c] = 'O'
            self._key_map[key] = (r, c)

    def _map_key_to_coord(self, key: str) -> Tuple[int, int]:
        """
        Deterministically maps a string configuration key to a (row, col) coordinate.
        Uses hash(key) for row and hash(key + salt) for col to distribute across 2D.
        """
        h_row = hash(key)
        h_col = hash(key + "_col_salt")

        row = abs(h_row) % self._board_size
        col = abs(h_col) % self._board_size
        return row, col

    def set_strategic_config(self, key: str, value: Any) -> bool:
        """
        Attempts to set a configuration value.
        Places 'X' if the calculated coordinate is empty.
        """
        r, c = self._map_key_to_coord(key)

        if self._board[r][c] is None:
            self._board[r][c] = 'X'
            self._cache[key] = value
            self._key_map[key] = (r, c)
            return True
        return False

    def get_config_value(self, key: str, default: Any) -> Any:
        """
        Retrieves a value. 
        Prioritizes cached values ('X'), then environment values ('O').
        """
        # Check cache (User set)
        if key in self._cache:
            return self._cache[key]

        # Check environment (System set)
        if key in self._env:
            return self._env[key]

        return default

    def check_structural_integrity(self) -> Optional[str]:
        """
        Scans the board for 5 consecutive symbols ('X' or 'O').
        Updates _integrity_verified flag.
        Returns the winning symbol or None.
        """
        directions = [(0, 1), (1, 0), (1, 1), (1, -1)]

        for r in range(self._board_size):
            for c in range(self._board_size):
                symbol = self._board[r][c]
                if symbol:
                    for dr, dc in directions:
                        if self._scan_direction(r, c, dr, dc):
                            self._integrity_verified = True
                            return symbol

        self._integrity_verified = False
        return None

    def _scan_direction(self, row: int, col: int, d_row: int, d_col: int) -> bool:
        """Internal helper to count consecutive matching pieces."""
        symbol = self._board[row][col]
        if not symbol:
            return False

        # Check next 4 positions (total 5 including start)
        for i in range(1, 5):
            nr, nc = row + d_row * i, col + d_col * i

            # Check bounds
            if not (0 <= nr < self._board_size and 0 <= nc < self._board_size):
                return False

            if self._board[nr][nc] != symbol:
                return False

        return True

    def is_production_ready(self) -> bool:
        """
        Determines if application is allowed to run in production.
        Requires integrity verified AND ENVIRONMENT='production'.
        """
        is_prod = self._env.get("ENVIRONMENT") == "production"
        return self._integrity_verified and is_prod

    def get_database_url(self) -> str:
        return str(self.get_config_value("DATABASE_URL", "sqlite:///:memory:"))

    def get_redis_host(self) -> str:
        return str(self.get_config_value("REDIS_HOST", "localhost"))

    def get_board_visual(self) -> str:
        """Returns ASCII art of the board."""
        lines = []
        for row in self._board:
            line = " ".join([cell if cell else "." for cell in row])
            lines.append(line)
        return "\n".join(lines)

class PersistentMemorySQLStore:
    def __init__(self, table_name, execution_mode='strict'):
        """
        Initializes the store with a target table and sets up the corresponding history table name.
        """
        self.primary_table = table_name
        self.history_table = f"{table_name}_history"
        self.execution_mode = execution_mode
        self.last_generated_query = None

    def _format_value(self, value):
        """Internal helper to format values for SQL strings."""
        if isinstance(value, str):
            return f"'{value}'"
        return str(value)

    def _generate_sql(self, operation, table, data=None, condition=None):
        """
        Internal helper method that handles the string construction logic for all public methods.
        """
        sql = ""
        if operation == 'SELECT':
            sql = f"SELECT * FROM {table}"
            if condition:
                sql += f" WHERE {condition}"
            sql += ";"

        elif operation == 'INSERT':
            if data:
                columns = ", ".join(data.keys())
                values = ", ".join([self._format_value(v) for v in data.values()])
                sql = f"INSERT INTO {table} ({columns}) VALUES ({values});"

        elif operation == 'UPDATE':
            if data:
                assignments = ", ".join([f"{k} = {self._format_value(v)}" for k, v in data.items()])
                sql = f"UPDATE {table} SET {assignments}"
                if condition:
                    sql += f" WHERE {condition}"
                sql += ";"

        elif operation == 'DELETE':
            sql = f"DELETE FROM {table}"
            if condition:
                sql += f" WHERE {condition}"
            sql += ";"

        return sql

    def get(self, memory_id):
        """
        Generates a SELECT statement to retrieve a specific memory by ID.
        """
        sql = self._generate_sql('SELECT', self.primary_table, condition=f"id = '{memory_id}'")
        return {'action': 'retrieve', 'sql': sql}

    def get_all(self):
        """
        Generates a SELECT statement to retrieve all current memory entries.
        """
        sql = self._generate_sql('SELECT', self.primary_table)
        return [sql]

    def store_new(self, data):
        """
        Generates an INSERT statement to create a new memory entry.
        """
        return self._generate_sql('INSERT', self.primary_table, data=data)

    def update(self, memory_id, data):
        """
        Performs a coupled transaction operation: archives current state to history, then updates primary.
        """
        # 1. Generate Archive SQL
        # Generates a statement to copy the current row to the history table
        archive_sql = f"INSERT INTO {self.history_table} SELECT * FROM {self.primary_table} WHERE id = '{memory_id}';"

        # 2. Generate Update SQL
        # Handle data conversion: if data is a simple string, assume it updates 'content'
        if isinstance(data, str):
            update_data = {'content': data}
        else:
            update_data = data

        update_sql = self._generate_sql('UPDATE', self.primary_table, data=update_data, condition=f"id = '{memory_id}'")

        # Combine into a single transaction script
        transaction_sql = f"{archive_sql} {update_sql}"

        return {'status': 'success', 'transaction_sql': transaction_sql}

    def delete(self, memory_id):
        """
        Generates a DELETE statement for the specific memory ID and updates last_generated_query.
        """
        sql = self._generate_sql('DELETE', self.primary_table, condition=f"id = '{memory_id}'")
        self.last_generated_query = sql

    def history(self, memory_id):
        """
        Generates a query to retrieve the version history of a memory from the shadow history table.
        """
        # Construct condition including the ORDER BY clause
        condition = f"original_id = '{memory_id}' ORDER BY timestamp DESC"
        sql = self._generate_sql('SELECT', self.history_table, condition=condition)
        return [sql]

    def select_memories_by_demographics(self, age_limit, gender_filter='female'):
        """
        Advanced filtering method that generates SQL based on specific metadata columns.
        """
        condition = f"age < {age_limit} AND gender = '{gender_filter}'"
        return self._generate_sql('SELECT', self.primary_table, condition=condition)

    def select_memories_by_age_range(self, min_age, max_age):
        """
        Generates a specialized SQL query using a BETWEEN clause.
        """
        condition = f"age BETWEEN {min_age} AND {max_age}"
        return self._generate_sql('SELECT', self.primary_table, condition=condition)

import xml.etree.ElementTree as ET
import warnings

class SemanticXMLRegistry:
    def __init__(self, file_path, initial_version=None):
        self.file_path = file_path
        self.root = None
        self.current_version_str = "0.0.0"
        self._version_tuple = (0, 0, 0)

        # Deprecation warning inherited from Version skeleton logic
        warnings.warn("Custom version parsing is deprecated; use packaging.version", DeprecationWarning, stacklevel=2)

        if initial_version:
            # Bootstrap new XML structure
            self.root = ET.Element("Configuration")
            meta = ET.SubElement(self.root, "Metadata")
            v_tag = ET.SubElement(meta, "Version")
            v_tag.text = initial_version
            self.current_version_str = initial_version
            self._version_tuple = self._parse_version(initial_version)

    def _parse_version(self, vstring):
        """Parses 'x.y.z' string into tuple (x, y, z)."""
        try:
            return tuple(map(int, vstring.split('.')))
        except ValueError:
            return (0, 0, 0)

    def read_xml(self):
        """Reads XML and synchronizes internal version state with the <Version> tag."""
        try:
            tree = ET.parse(self.file_path)
            self.root = tree.getroot()

            # Find version in XML to update internal state
            # Assuming structure <Configuration><Metadata><Version>...</Version></Metadata>...</Configuration>
            meta = self.root.find(".//Version")
            if meta is not None and meta.text:
                self.current_version_str = meta.text
                self._version_tuple = self._parse_version(meta.text)

            return self.root
        except (ET.ParseError, FileNotFoundError):
            return None

    def _cmp(self, other):
        """Core comparison logic implementation."""
        other_tuple = None
        if isinstance(other, SemanticXMLRegistry):
            other_tuple = other._version_tuple
        elif isinstance(other, str):
            other_tuple = self._parse_version(other)
        elif isinstance(other, tuple):
            other_tuple = other
        else:
            return NotImplemented

        if self._version_tuple < other_tuple:
            return -1
        elif self._version_tuple > other_tuple:
            return 1
        else:
            return 0

    # Comparison Magic Methods delegating to _cmp
    def __eq__(self, other):
        c = self._cmp(other)
        if c is NotImplemented: return NotImplemented
        return c == 0

    def __lt__(self, other):
        c = self._cmp(other)
        if c is NotImplemented: return NotImplemented
        return c < 0

    def __le__(self, other):
        c = self._cmp(other)
        if c is NotImplemented: return NotImplemented
        return c <= 0

    def __gt__(self, other):
        c = self._cmp(other)
        if c is NotImplemented: return NotImplemented
        return c > 0

    def __ge__(self, other):
        c = self._cmp(other)
        if c is NotImplemented: return NotImplemented
        return c >= 0

    def find_element(self, element_name):
        """Finds all elements with a specific tag name."""
        if self.root is None:
            return []
        return self.root.findall(f".//{element_name}")

    def write_xml(self, file_name=None):
        """Syncs version state to XML tree and writes to disk."""
        target_file = file_name if file_name else self.file_path
        if self.root is None:
            return False

        # Ensure XML reflects current internal version state
        meta = self.root.find(".//Version")
        if meta is None:
            # Create if missing
            # Check for direct Metadata child to enforce schema
            m = self.root.find("Metadata")
            if m is None:
                m = ET.SubElement(self.root, "Metadata")
            meta = ET.SubElement(m, "Version")

        meta.text = self.current_version_str

        try:
            tree = ET.ElementTree(self.root)
            tree.write(target_file, encoding='utf-8', xml_declaration=True)
            return True
        except IOError:
            return False

    def apply_versioned_migration(self, target_version, transformation_callback):
        """
        Cross-domain method: Checks version (Version domain) before modifying data (XML domain).
        Only applies changes if target_version > current_version.
        """
        if self.root is None:
            return False

        # Use internal comparison logic
        if self < target_version:
            # Apply DOM transformation
            try:
                transformation_callback(self.root)

                # Update State
                self.current_version_str = target_version
                self._version_tuple = self._parse_version(target_version)

                # Persist
                return self.write_xml()
            except Exception as e:
                print(f"Migration failed: {e}")
                return False
        else:
            print(f"Skipping migration: Current {self.current_version_str} >= Target {target_version}")
            return False

import sys

class VisualAccessServer:
    def __init__(self, force_colors=None):
        """
        Initializes the server state and formatting engine.
        """
        self.access_whitelist = []
        self.last_transaction = {}
        self._ansi_map = {
            'RED': '\033[91m',
            'GREEN': '\033[92m',
            'BLUE': '\033[94m',
            'YELLOW': '\033[93m',
            'BOLD': '\033[1m',
            'RESET': '\033[0m'
        }

        if force_colors is not None:
            self.color_enabled = force_colors
        else:
            self.color_enabled = sys.stdout.isatty()

    def _style(self, text, style_key):
        """
        Internal helper that applies ANSI codes to text if color_enabled is True.
        """
        if not self.color_enabled:
            return text

        code = self._ansi_map.get(style_key, '')
        reset = self._ansi_map.get('RESET', '')
        return f"{code}{text}{reset}"

    def _format_success(self, text):
        """
        Internal semantic wrapper that applies the "GREEN" style to indicate successful server operations.
        """
        return self._style(f"[SUCCESS] {text}", "GREEN")

    def _format_error(self, text):
        """
        Internal semantic wrapper that applies the "RED" style to indicate security violations.
        """
        return self._style(f"[ERROR] {text}", "RED")

    def authorize_client(self, addr):
        """
        Adds an address to the whitelist.
        """
        if addr in self.access_whitelist:
            return self._style(f"Address {addr} already in whitelist.", "YELLOW")

        self.access_whitelist.append(addr)
        return self._format_success(f"Address {addr} added to whitelist.")

    def revoke_client(self, addr):
        """
        Removes an address from the whitelist.
        """
        if addr in self.access_whitelist:
            self.access_whitelist.remove(addr)
            return self._style(f"Address {addr} removed from whitelist.", "BLUE")

        return self._format_error(f"Address {addr} not found.")

    def process_ingress(self, packet):
        """
        Receives and validates an incoming data packet.
        """
        addr = packet.get("addr")
        content = packet.get("content")

        if addr in self.access_whitelist:
            self.last_transaction = packet
            # Apply Bold, then Green
            styled_content = self._style(content, "BOLD")
            return self._style(styled_content, "GREEN")
        else:
            return self._format_error(f"Access Denied for {addr}")

    def dispatch_egress(self, packet):
        """
        Simulates sending data.
        """
        self.last_transaction = packet
        addr = packet.get("addr")
        content = packet.get("content")
        return self._style(f"Dispatching to {addr}: {content}", "BLUE")

    def inspect_state(self, target):
        """
        Returns the internal state of the server formatted for console display.
        """
        if target == "whitelist":
            return self._style(str(self.access_whitelist), "BOLD")
        elif target == "transaction":
            return self._style(str(self.last_transaction), "BOLD")
        else:
            return self._style("Invalid Target", "RED")

import datetime

class RestfulMessenger:
    def __init__(self):
        """
        Initializes the messaging storage and populates the internal protocol definitions.
        """
        self._user_store = {}
        self._status_map = {
            200: "OK",
            201: "Created",
            400: "Bad Request",
            404: "Not Found",
            409: "Conflict",
            500: "Internal Server Error"
        }
        self.last_code = 200
        self.last_phrase = "OK"

    def add_user(self, username):
        """
        Registers a new user in the system.
        Returns 201 (Created) or 409 (Conflict).
        """
        if username in self._user_store:
            return self._update_state(409)

        self._user_store[username] = []
        return self._update_state(201)

    def remove_user(self, username):
        """
        Deletes a user from the system.
        Returns 200 (OK) or 404 (Not Found).
        """
        if username not in self._user_store:
            return self._update_state(404)

        del self._user_store[username]
        return self._update_state(200)

    def send_message(self, sender, receiver, message):
        """
        Routes a message between users.
        Returns 200 (OK), 400 (Bad Request), or 404 (Not Found).
        """
        # Validate participants
        if sender not in self._user_store or receiver not in self._user_store:
            return self._update_state(404)

        # Validate message content
        if not message:
            return self._update_state(400)

        timestamp = datetime.datetime.now()
        msg_entry = {
            "sender": sender,
            "receiver": receiver,
            "message": message,
            "timestamp": timestamp
        }

        # Add to receiver's history
        self._user_store[receiver].append(msg_entry)

        # Add to sender's history (if not self-messaging) to maintain conversation context
        if sender != receiver:
            self._user_store[sender].append(msg_entry)

        return self._update_state(200)

    def get_messages(self, username):
        """
        Retrieves message history for a user.
        Returns list or None. Sets state to 200 or 404.
        """
        if username not in self._user_store:
            self._update_state(404)
            return None

        self._update_state(200)
        return self._user_store[username]

    def get_reason_phrase(self, code):
        """
        Retrieves the text description for a specific status code.
        """
        return self._status_map.get(code, "Unknown Status")

    def is_success(self, code):
        """
        Determines if a status code represents a successful operation (2xx).
        """
        return 200 <= code <= 299

    def is_client_error(self, code):
        """
        Determines if a status code represents a client-side error (4xx).
        """
        return 400 <= code <= 499

    def is_error(self, code):
        """
        Checks if the code indicates any type of failure (4xx or 5xx).
        """
        return code >= 400

    def _update_state(self, code):
        """
        Internal helper that updates last_code and last_phrase.
        """
        self.last_code = code
        self.last_phrase = self.get_reason_phrase(code)
        return code

from typing import Any, Dict, List

class CamelAttrDict:
    def __init__(self, initial_data: Dict[str, Any]):
        """
        Initializes the object and populates the internal storage by passing 
        the raw input data through the internal transformation logic.
        """
        # Initialize internal storage. 
        # The __setattr__ guard clause handles the assignment to _data 
        # because it starts with an underscore.
        self._data = {}
        for key, value in initial_data.items():
            self[key] = value

    def __getattr__(self, name: str) -> Any:
        """
        Intercepts attribute access to retrieve values from the dictionary, 
        creating a dependency chain that relies on __getitem__ to handle key normalization.
        """
        return self[name]

    def __setattr__(self, name: str, value: Any) -> None:
        """
        Intercepts attribute assignment to route data into the dictionary storage, 
        delegating to __setitem__ to ensure the key is properly camel-cased before storage.
        """
        # Guard clause: allow writing to private fields (like _data) 
        # without triggering the dictionary logic.
        if name.startswith("_"):
            super().__setattr__(name, value)
        else:
            self[name] = value

    def __getitem__(self, key: str) -> Any:
        """
        Retrieves a value using bracket syntax. It attempts to find the key directly; 
        if missing, it invokes _convert_key to check for a camelCase version.
        """
        if key in self._data:
            return self._data[key]

        camel_key = self._convert_key(key)
        if camel_key in self._data:
            return self._data[camel_key]

        raise KeyError(key)

    def __setitem__(self, key: str, value: Any) -> None:
        """
        Assigns a value using bracket syntax. It explicitly calls _convert_key 
        to transform the input key into camelCase before writing to _data.
        """
        camel_key = self._convert_key(key)
        self._data[camel_key] = value

    def get(self, key: str, default: Any = None) -> Any:
        """
        A safe retrieval method that leverages the internal __getitem__ logic 
        to handle key normalization, returning a default if the key is missing.
        """
        try:
            return self[key]
        except KeyError:
            return default

    def _convert_key(self, key: str) -> str:
        """
        An internal coordination method that links the public interface 
        to the static transformation logic.
        """
        return self._to_camel_case(key)

    @staticmethod
    def _to_camel_case(key: str) -> str:
        """
        A static helper containing the pure algorithmic logic to transform 
        a snake_case string into camelCase.
        """
        parts = key.split('_')
        if not parts:
            return ""
        # The first part is kept as-is (usually lowercase), 
        # subsequent parts are capitalized.
        return parts[0] + ''.join(word.capitalize() for word in parts[1:])

    def keys(self):
        """
        Returns a view of the keys currently stored in the internal dictionary.
        """
        return self._data.keys()

    def __contains__(self, key: str) -> bool:
        """
        Checks for existence of a key, utilizing the normalization logic.
        """
        if key in self._data:
            return True
        return self._convert_key(key) in self._data

    def __dir__(self) -> List[str]:
        """
        Customizes autocomplete/introspection to list the dynamic dictionary keys 
        alongside standard class methods.
        """
        return list(self.keys()) + list(super().__dir__())

    def __repr__(self) -> str:
        """
        Returns the string representation of the internal normalized data.
        """
        return repr(self._data)

class TaggedInventoryBuffer:
    def __init__(self):
        """
        Initialize the TaggedInventoryBuffer with empty items, empty tags, and zero valuation.
        """
        self.items = {}
        self.tags = set()
        self.current_valuation = 0.0

    def add_inventory_item(self, item, price, quantity=1):
        """
        Adds an item to the inventory, but only if the buffer is not tagged as "LOCKED".
        Triggers a valuation update.
        """
        # Tag-Gated Write Access: Check if LOCKED tag is present
        if not self._excludes_tags(["LOCKED"]):
            return False

        if item in self.items:
            self.items[item]['quantity'] += quantity
            self.items[item]['price'] = price  # Update to most recent price
        else:
            self.items[item] = {'price': price, 'quantity': quantity}

        self._recalculate_valuation()
        return True

    def remove_inventory_item(self, item, quantity=1):
        """
        Removes quantity of an item. Triggers a valuation update upon success.
        """
        if item in self.items:
            if self.items[item]['quantity'] <= quantity:
                del self.items[item]
            else:
                self.items[item]['quantity'] -= quantity

            self._recalculate_valuation()

    def modify_tags(self, tags_to_add=None, tags_to_remove=None):
        """
        Updates the buffer's tag set. Forces a recalculation of the current_valuation.
        """
        if tags_to_add:
            self.tags.update(tags_to_add)

        if tags_to_remove:
            self.tags.difference_update(tags_to_remove)

        self._recalculate_valuation()

    def get_buffered_value(self):
        """
        Retrieves the current_valuation.
        """
        return self.current_valuation

    def validate_and_checkout(self, required_tags, forbidden_tags):
        """
        Performs a logic check using buffer tag operations to determine if the inventory is valid for processing.
        """
        if self._includes_tags(required_tags) and self._excludes_tags(forbidden_tags):
            return self.items
        return None

    def _recalculate_valuation(self):
        """
        Internal helper that computes the raw total from items, checks tags for modifiers, and updates current_valuation.
        """
        raw_total = sum(item['price'] * item['quantity'] for item in self.items.values())

        # State-Dependent Valuation: Apply VIP discount if applicable
        if self._includes_tags(["VIP_DISCOUNT"]):
            raw_total *= 0.9

        self.current_valuation = raw_total

    def _includes_tags(self, target_tags):
        """
        Internal helper to check if the buffer contains all specified tags.
        """
        return self.tags.issuperset(target_tags)

    def _excludes_tags(self, target_tags):
        """
        Internal helper to check if the buffer contains none of the specified tags.
        """
        return self.tags.isdisjoint(target_tags)

class HTTPInventoryGateway:
    def __init__(self):
        """
        Initialize the gateway with an empty inventory and transaction log.
        """
        self._inventory = {}
        self._transaction_log = []

    def resolve_phrase(self, status_code):
        """
        Utility method to translate numeric status codes into human-readable reason phrases.
        """
        phrases = {
            200: "OK",
            201: "Created",
            400: "Bad Request",
            404: "Not Found",
            409: "Conflict",
            500: "Internal Server Error",
            503: "Service Unavailable"
        }
        return phrases.get(status_code, "Unknown Status")

    def _create_response(self, status_code, data=None):
        """
        Internal helper to log the transaction and format the response dictionary.
        """
        self._transaction_log.append(status_code)
        return {
            "status": status_code,
            "phrase": self.resolve_phrase(status_code),
            "data": data if data is not None else {}
        }

    def upsert_book(self, title, quantity=1):
        """
        Adds a book or updates its quantity.
        Returns 201 for new books, 200 for updates, 400 for invalid quantity.
        """
        if quantity < 1:
            return self._create_response(400)

        if title in self._inventory:
            self._inventory[title] += quantity
            return self._create_response(200)
        else:
            self._inventory[title] = quantity
            return self._create_response(201)

    def remove_book(self, title, quantity):
        """
        Attempts to remove stock.
        Returns 404 if not found, 409 if conflict (insufficient stock), 200 if successful.
        """
        if title not in self._inventory:
            return self._create_response(404)

        if quantity > self._inventory[title]:
            return self._create_response(409)

        self._inventory[title] -= quantity
        return self._create_response(200)

    def get_book_status(self, title):
        """
        Retrieves the quantity of a specific book.
        Returns 200 with data if found, 404 if not found.
        """
        if title in self._inventory:
            return self._create_response(200, {"quantity": self._inventory[title]})
        else:
            return self._create_response(404)

    def audit_last_transaction(self):
        """
        Analyzes the most recent operation's status code.
        Returns a category string based on the status code range.
        """
        if not self._transaction_log:
            return "Unknown"

        last_code = self._transaction_log[-1]

        if 200 <= last_code <= 299:
            return "Success"
        elif 400 <= last_code <= 499:
            return "Client Error"
        elif 500 <= last_code <= 599:
            return "Server Error"
        else:
            return "Unknown"

