    def __init__(self):
        self.written_data = ""
        self.read_data = ""
        self.is_closed = False
        self._fd = 101

    def write(self, text):
        if self.is_closed:
            raise ValueError("I/O operation on closed file")
        self.written_data += text
        return len(text)

    def read(self, size=None):
        if self.is_closed:
