import sys

class HierarchicalCombinator(tuple):
    def __new__(cls, *args):
        return super(HierarchicalCombinator, cls).__new__(cls, args)

    def __init__(self, *args):
        # Prevent re-initialization if already set up (due to singleton/copy patterns)
        if not hasattr(self, "_initialized"):
            self._subtypes = set()
            self._parent = None
            self._inventory = []  # The 'datas' from Calculator
            self._initialized = True

    def __getattr__(self, name):
        # Only process uppercase attributes as hierarchy nodes
        if name and name[0].isupper():
            # Check if subtype already exists to maintain singleton-like graph
            for subtype in self._subtypes:
                if subtype[-1] == name:
                    return subtype

            # Create new node extending the path
            new_path = self + (name,)
            new_instance = HierarchicalCombinator(*new_path)
            new_instance._parent = self
            self._subtypes.add(new_instance)
            return new_instance

        # Fallback to standard attribute access (will raise AttributeError)
        return super().__getattribute__(name)

    def ingest(self, *elements):
        self._inventory.extend(elements)

    def split(self):
        if self._parent:
            return self._parent.split() + [self]
        return [self]

    def __repr__(self):
        return ".".join(str(x) for x in self)

    def __contains__(self, val):
        if self is val:
            return True
        return any(val in subtype for subtype in self._subtypes)

    def __copy__(self):
        return self

    def __deepcopy__(self, memo):
        return self

    # --- Combinatorial Logic ---

    def count_possibilities(self, m=None):
        n = len(self._inventory)

        # Logic for count_all (total non-empty combinations)
        if m is None:
            limit = (2**63) - 1
            # 2^n - 1 represents all non-empty subsets
            try:
                total = (1 << n) - 1
                return float("inf") if total > limit else total
            except OverflowError:
                return float("inf")

        # Logic for nCr
        if m < 0 or m > n:
            return 0
        if m == 0 or m == n:
            return 1
        if m > n // 2:
            m = n - m

        numerator = 1
        for i in range(m):
            numerator *= (n - i)

        denominator = 1
        for i in range(1, m + 1):
            denominator *= i

        return numerator // denominator

    def generate_scoped_selection(self, m):
        results = []
        # Coupling: Use internal math logic with internal inventory state
        self._backtrack(0, [], m, results)
        return results

    def _backtrack(self, start_index, current_combo, target_size, results_list):
        if len(current_combo) == target_size:
            # Coupling: Combine Token identity (__repr__) with Calculator output
            formatted_output = f"{self.__repr__()}::{current_combo}"
            results_list.append(formatted_output)
            return

        for i in range(start_index, len(self._inventory)):
            current_combo.append(self._inventory[i])
            self._backtrack(i + 1, current_combo, target_size, results_list)
            current_combo.pop()

import sys
import os
from typing import Dict, List, Tuple, Any, Optional

class EvaluatedConfigDiscovery:
    def __init__(self, env_overrides: Optional[Dict[str, str]] = None):
        """
        Initializes the evaluator with optional environment variable overrides 
        and prepares the empty history log.
        """
        self._discovered_paths: Dict[str, List[str]] = {}
        self._retrieval_history: List[Tuple[List[int], int]] = []
        self._env_config: Dict[str, str] = env_overrides or {}
        self._resource_paths: Dict[str, Any] = {
            'yara': self._resolve_resource_path('yara'),
            'prompts': self._resolve_resource_path('prompts')
        }

    def perform_scan_and_grade(self, ground_truth_total: int) -> Dict[str, float]:
        """
        Executes a full scan lifecycle: detects platform paths, validates them,
        records the "hit/miss" pattern, and returns immediate metrics.
        """
        # 1. Domain 1: Detect paths
        flat_paths = self._detect_platform_paths()

        # 2. Hybrid: Validate paths to create binary vector
        # We expand user (~) and vars (%) to ensure paths are absolute and validatable
        result_vector = []
        for p in flat_paths:
            # Expand environment variables (like %APPDATA%) and user home (~)
            resolved_path = os.path.expandvars(os.path.expanduser(p))
            result_vector.append(1 if os.path.exists(resolved_path) else 0)

        # 3. Store in history (Domain 2 State)
        self._retrieval_history.append((result_vector, ground_truth_total))

        # 4. Domain 2: Calculate immediate metrics
        mrr = self._calculate_mrr_score(result_vector)
        ap = self._calculate_map_score(result_vector, ground_truth_total)

        return {'mrr': mrr, 'map': ap}

    def get_cumulative_metrics(self) -> Tuple[float, float]:
        """
        Calculates the Mean Reciprocal Rank (MRR) and Mean Average Precision (MAP) 
        across all recorded scan sessions.
        """
        if not self._retrieval_history:
            return 0.0, 0.0

        total_mrr = sum(self._calculate_mrr_score(r) for r, _ in self._retrieval_history)
        total_map = sum(self._calculate_map_score(r, gt) for r, gt in self._retrieval_history)

        count = len(self._retrieval_history)
        return (total_mrr / count, total_map / count)

    def get_smart_diagnostic_message(self) -> str:
        """
        Generates a context-aware error or status message based on current metrics.
        """
        avg_mrr, _ = self.get_cumulative_metrics()

        # Cross-Domain Logic: Message depends on Metric Score
        if avg_mrr >= 0.8:
            return "System Healthy: Configuration discovery is optimal."

        # Domain 1 Logic: Construct specific error strings
        # Check if custom variable names are defined in config, else use defaults
        api_key_var = self._env_config.get('ENV_API_KEY', 'MCP_SCANNER_API_KEY')
        yara_var = self._env_config.get('ENV_YARA_DIR', 'MCP_SCANNER_YARA_RULES_DIR')

        msg = (f"Critical: Discovery MRR is low ({avg_mrr:.2f}). "
               f"Ensure '{yara_var}' points to valid rules and "
               f"'{api_key_var}' is set correctly.")
        return msg

    def _detect_platform_paths(self) -> List[str]:
        """
        Internal helper that populates _discovered_paths based on the current operating system.
        """
        paths = {}
        if sys.platform == "linux" or sys.platform.startswith("linux"):
            paths = {
                "vscode": ["~/.config/Code/User/globalStorage/mcp.json"],
                "cursor": ["~/.config/Cursor/User/globalStorage/mcp.json"]
            }
        elif sys.platform == "darwin": # macOS
            paths = {
                "vscode": ["~/Library/Application Support/Code/User/globalStorage/mcp.json"],
                "cursor": ["~/Library/Application Support/Cursor/User/globalStorage/mcp.json"]
            }
        elif sys.platform == "win32":
            paths = {
                "vscode": ["%APPDATA%\\Code\\User\\globalStorage\\mcp.json"],
                "cursor": ["%APPDATA%\\Cursor\\User\\globalStorage\\mcp.json"]
            }
        else:
            # Fallback for unknown platforms
            paths = {"vscode": [], "cursor": []}

        self._discovered_paths = paths
        # Flatten for evaluation
        return [p for sublist in paths.values() for p in sublist]

    def _resolve_resource_path(self, resource_type: str) -> str:
        """
        Resolves internal paths for 'yara' or 'prompts', prioritizing environment variables.
        """
        # Priority: Env Override -> Default Package Path
        # The key is constructed as MCP_SCANNER_{TYPE}_RULES_DIR
        env_key = f"MCP_SCANNER_{resource_type.upper()}_RULES_DIR"
        if env_key in self._env_config:
            return self._env_config[env_key]

        # Default: cwd/resources/{type}
        return os.path.join(os.getcwd(), "resources", resource_type)

    def _calculate_mrr_score(self, result_vector: List[int]) -> float:
        """
        Computes the Reciprocal Rank for a single result vector.
        """
        for i, val in enumerate(result_vector):
            if val == 1:
                return 1.0 / (i + 1)
        return 0.0

    def _calculate_map_score(self, result_vector: List[int], ground_truth_num: int) -> float:
        """
        Computes Average Precision (AP) for a single result vector.
        """
        if ground_truth_num <= 0:
            return 0.0

        score = 0.0
        hits = 0
        for i, val in enumerate(result_vector):
            if val == 1:
                hits += 1
                score += hits / (i + 1)

        return score / ground_truth_num

