import math

class LexicalNumberGraphProvider:
    def __init__(self):
        self._digits = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        self._teens = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN", "EIGHTEEN", "NINETEEN"]
        self._tens = ["", "", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        self._magnitudes = ["", "THOUSAND", "MILLION", "BILLION"]
        self._resolution_cache = {}

        # Initialize parsing map for reverse lookup
        self._word_to_val = {"ZERO": 0}
        for i, w in enumerate(self._digits):
            if w: self._word_to_val[w] = i
        for i, w in enumerate(self._teens):
            self._word_to_val[w] = 10 + i
        for i, w in enumerate(self._tens):
            if w: self._word_to_val[w] = i * 10
        self._word_to_val["HUNDRED"] = 100
        self._word_to_val["THOUSAND"] = 1000
        self._word_to_val["MILLION"] = 1000000
        self._word_to_val["BILLION"] = 1000000000

    def identify(self, requirement_or_candidate):
        """Generates a unique semantic identifier for a number by converting it into its English word representation."""
        if requirement_or_candidate in self._resolution_cache:
            return self._resolution_cache[requirement_or_candidate]

        result = self._format_number(requirement_or_candidate)
        self._resolution_cache[requirement_or_candidate] = result
        return result

    def get_preference(self, identifier, resolutions, candidates, information, backtrack_causes):
        """Calculates resolution priority based on lexical complexity (length of the identifier)."""
        return len(identifier)

    def find_matches(self, identifier, requirements, incompatibilities):
        """Generates candidate numbers that semantically match the given identifier."""
        try:
            val = self._parse_english_number(identifier)
            # Check incompatibilities
            if val in incompatibilities:
                return
            # Yield the match
            yield val
        except ValueError:
            return

    def is_satisfied_by(self, requirement, candidate):
        """Validates if a candidate number satisfies a requirement (substring check)."""
        text = self.identify(candidate)
        return requirement in text

    def get_dependencies(self, candidate):
        """Deconstructs a number into its linguistic roots (constituent numbers)."""
        text = self.identify(candidate)
        words = text.split()
        deps = []
        for w in words:
            if w in self._word_to_val:
                val = self._word_to_val[w]
                deps.append(val)
        return deps

    def _format_number(self, x):
        """Core internal engine that converts an integer to English text."""
        if x == 0:
            return "ZERO"

        parts = []
        s_x = str(x)
        # Pad to ensure length is multiple of 3
        padding = (3 - len(s_x) % 3) % 3
        s_x = "0" * padding + s_x

        chunks = [s_x[i:i+3] for i in range(0, len(s_x), 3)]
        total_chunks = len(chunks)

        for i, chunk in enumerate(chunks):
            val = int(chunk)
            if val == 0:
                continue

            chunk_text = self._trans_triplet(chunk)
            mag_index = total_chunks - 1 - i
            magnitude = self._parse_magnitude(mag_index)

            parts.append(chunk_text)
            if magnitude:
                parts.append(magnitude)

        return " ".join(parts)

    def _trans_triplet(self, s):
        """Helper method to process 3-digit chunks."""
        val = int(s)
        parts = []

        hundreds = val // 100
        remainder = val % 100

        if hundreds > 0:
            parts.append(self._digits[hundreds])
            parts.append("HUNDRED")

        if remainder > 0:
            parts.append(self._trans_pair(str(remainder)))

        return " ".join(parts)

    def _trans_pair(self, s):
        """Helper method to process 2-digit chunks."""
        val = int(s)
        if val < 10:
            return self._digits[val]
        elif val < 20:
            return self._teens[val - 10]
        else:
            tens = val // 10
            units = val % 10
            text = self._tens[tens]
            if units > 0:
                text += " " + self._digits[units]
            return text

    def _parse_magnitude(self, index):
        """Retrieves the appropriate suffix based on triplet index."""
        if 0 <= index < len(self._magnitudes):
            return self._magnitudes[index]
        return ""

    def _parse_english_number(self, text):
        """Parses English number text back to integer."""
        words = text.split()
        total_value = 0
        current_chunk_value = 0

        for w in words:
            if w not in self._word_to_val:
                raise ValueError(f"Unknown word: {w}")

            val = self._word_to_val[w]

            if val == 100:
                # Multiplies the current small chunk (e.g., "TWO" -> 2 -> 200)
                current_chunk_value *= val
            elif val >= 1000:
                # Multiplies the accumulated chunk and adds to total
                total_value += current_chunk_value * val
                current_chunk_value = 0
            else:
                # Adds to current chunk (e.g., "TWENTY" + "ONE")
                current_chunk_value += val

        total_value += current_chunk_value
        return total_value

import os
import random
from collections import deque
from typing import Any, List, Tuple, Dict, Optional

class MahjongConfigurationContext:
    def __init__(self):
        self._env = os.environ
        self._config_cache: Dict[str, Any] = {}
        self._board: List[List[str]] = []
        self._active_icons: List[str] = []

    def initialize_session(self) -> None:
        """
        Bootstraps the hybrid session by loading environment variables, 
        determining the "icon set" based on available API keys, and generating the board.
        """
        self._active_icons = self._derive_icons_from_config()
        self._board = self.create_board()

    def get_database_url(self) -> str:
        """Retrieves the database URL."""
        return str(self.get_config_value("DATABASE_URL", "sqlite:///maverick_mcp.db"))

    def get_pool_size(self) -> int:
        """Retrieves the DB pool size, which also dictates the number of rows in the game board."""
        return int(self.get_config_value("DB_POOL_SIZE", 6))

    def get_max_overflow(self) -> int:
        """Retrieves max overflow, which also dictates the number of columns in the game board."""
        return int(self.get_config_value("DB_MAX_OVERFLOW", 10))

    def is_production_mode(self) -> bool:
        """Checks if running in production."""
        env = self.get_config_value("ENVIRONMENT", "development")
        if isinstance(env, str):
            return env.lower() == "production"
        return False

    def get_fred_api_key(self) -> Optional[str]:
        """Retrieves FRED API key."""
        return self.get_config_value("FRED_API_KEY", None)

    def get_tiingo_api_key(self) -> Optional[str]:
        """Retrieves Tiingo API key."""
        return self.get_config_value("TIINGO_API_KEY", None)

    def get_redis_config(self) -> Dict[str, Any]:
        """Aggregates Redis settings (Host, Port, DB) into a dict."""
        host = self.get_config_value("REDIS_HOST", None)
        if host:
            return {
                "host": host,
                "port": self.get_config_value("REDIS_PORT", 6379),
                "db": self.get_config_value("REDIS_DB", 0)
            }
        return {}

    def _derive_icons_from_config(self) -> List[str]:
        """Internal helper that builds the _active_icons list."""
        icons = ["DEFAULT", "SERVER", "CLIENT", "NETWORK", "CACHE"]

        if self.get_fred_api_key():
            icons.append("FRED")

        if self.get_tiingo_api_key():
            icons.append("TIINGO")

        redis_conf = self.get_redis_config()
        if redis_conf and "host" in redis_conf:
            icons.append("REDIS")

        return icons

    def create_board(self) -> List[List[str]]:
        """Generates the grid using dimensions from config."""
        rows = self.get_pool_size()
        cols = self.get_max_overflow()

        if not self._active_icons:
            self._active_icons = self._derive_icons_from_config()

        total_cells = rows * cols
        # Ensure we have pairs
        tiles = []
        while len(tiles) < total_cells:
            icon = random.choice(self._active_icons)
            tiles.append(icon)
            tiles.append(icon)

        # Trim to exact size (though rows*cols should be even usually)
        tiles = tiles[:total_cells]
        random.shuffle(tiles)

        board = []
        for r in range(rows):
            start = r * cols
            end = start + cols
            board.append(tiles[start:end])

        return board

    def get_current_board(self) -> List[List[str]]:
        """Returns the current state of the board."""
        return self._board

    def execute_move(self, pos1: Tuple[int, int], pos2: Tuple[int, int]) -> bool:
        """
        The primary interaction method. Validates the move, removes icons, 
        and updates the _config_cache.
        """
        if self.is_valid_move(pos1, pos2):
            self._remove_icons(pos1, pos2)
            self.set_config_value("CURRENT_BOARD_STATE", self._board)
            return True
        return False

    def is_valid_move(self, pos1: Tuple[int, int], pos2: Tuple[int, int]) -> bool:
        """Checks boundary conditions, icon matching, and path connectivity."""
        rows = len(self._board)
        if rows == 0: return False
        cols = len(self._board[0])

        r1, c1 = pos1
        r2, c2 = pos2

        # Boundary checks
        if not (0 <= r1 < rows and 0 <= c1 < cols): return False
        if not (0 <= r2 < rows and 0 <= c2 < cols): return False

        # Same position check
        if pos1 == pos2: return False

        # Icon matching and existence
        icon1 = self._board[r1][c1]
        icon2 = self._board[r2][c2]

        if not icon1 or not icon2: return False
        if icon1 != icon2: return False

        return self.has_path(pos1, pos2)

    def has_path(self, pos1: Tuple[int, int], pos2: Tuple[int, int]) -> bool:
        """
        Pathfinding algorithm (BFS). Uses is_production_mode() to determine 
        the maximum allowed turns (2 for prod, 3 for dev).
        """
        rows = len(self._board)
        cols = len(self._board[0])
        max_turns = 2 if self.is_production_mode() else 3

        # Queue stores: (row, col, turns, direction_enum)
        # direction_enum: 0=None, 1=Up, 2=Down, 3=Left, 4=Right
        queue = deque([(pos1[0], pos1[1], 0, 0)])

        # Visited stores: (row, col, direction) -> min_turns
        visited = {}

        # (dr, dc, dir_enum)
        moves = [(-1, 0, 1), (1, 0, 2), (0, -1, 3), (0, 1, 4)]

        while queue:
            r, c, turns, last_dir = queue.popleft()

            if (r, c) == pos2:
                return True

            for dr, dc, new_dir in moves:
                nr, nc = r + dr, c + dc

                if 0 <= nr < rows and 0 <= nc < cols:
                    # Calculate turns
                    new_turns = turns
                    if last_dir != 0 and last_dir != new_dir:
                        new_turns += 1

                    if new_turns > max_turns:
                        continue

                    # Check obstruction: must be empty or target
                    if (nr, nc) != pos2 and self._board[nr][nc] != "":
                        continue

                    # Optimization: check if we've reached this state with fewer or equal turns
                    state_key = (nr, nc, new_dir)
                    if state_key in visited and visited[state_key] <= new_turns:
                        continue

                    visited[state_key] = new_turns
                    queue.append((nr, nc, new_turns, new_dir))

        return False

    def _remove_icons(self, pos1: Tuple[int, int], pos2: Tuple[int, int]) -> None:
        """Internal method to clear tiles at specified positions."""
        r1, c1 = pos1
        r2, c2 = pos2
        self._board[r1][c1] = ""
        self._board[r2][c2] = ""

    def get_config_value(self, key: str, default: Any) -> Any:
        """Retrieves generic values. Checks _config_cache first, then _env."""
        if key in self._config_cache:
            return self._config_cache[key]
        return self._env.get(key, default)

    def set_config_value(self, key: str, value: Any) -> None:
        """Stores values in _config_cache."""
        self._config_cache[key] = value

    def reload_config(self) -> None:
        """Resets the internal cache and the game board."""
        self._config_cache.clear()
        self.initialize_session()

    def is_game_over(self) -> bool:
        """Checks if the board is empty."""
        if not self._board:
            return True
        for row in self._board:
            for cell in row:
                if cell != "":
                    return False
        return True

class StreamableOrderSession:
    def __init__(self):
        """Initializes the order session with empty selections and a reset stream cursor."""
        self.menu = []
        self.selected_dishes = []
        self.sales = {}
        self._cursor = 0
        self._buffer = ""
        self._is_closed = False

    def add_dish(self, dish):
        """
        Core logic to update inventory and selection state.
        Validates availability in menu and updates selected_dishes.
        """
        # Validate input structure
        if not isinstance(dish, dict):
            return False
        if not all(key in dish for key in ("dish", "price", "count")):
            return False

        target_name = dish["dish"]
        target_count = dish["count"]

        # Find item in menu
        menu_item = None
        for item in self.menu:
            if item["name"] == target_name:
                menu_item = item
                break

        # Validate existence and inventory
        if menu_item is None:
            return False
        if menu_item["count"] < target_count:
            return False

        # Update inventory
        menu_item["count"] -= target_count

        # Add to selected dishes
        self.selected_dishes.append(dish)
        return True

    def write(self, text):
        """
        Parses a string input to add items to the order.
        Format: "DishName,Price,Count"
        """
        if self._is_closed:
            return 0

        if not text:
            return 0

        try:
            parts = text.split(',')
            if len(parts) != 3:
                return 0

            name = parts[0].strip()
            price = float(parts[1].strip())
            count = int(parts[2].strip())

            dish = {"dish": name, "price": price, "count": count}

            if self.add_dish(dish):
                return len(text)
            else:
                return 0
        except ValueError:
            return 0

    def calculate_total(self):
        """Computes the current total cost by applying sales multipliers."""
        total = 0.0
        for item in self.selected_dishes:
            name = item["dish"]
            price = item["price"]
            count = item["count"]

            multiplier = self.sales.get(name, 1.0)
            total += (price * count * multiplier)
        return total

    def _update_buffer(self):
        """Internal helper to regenerate the receipt buffer."""
        lines = ["Order Summary:"]
        for item in self.selected_dishes:
            lines.append(f"- {item['dish']} (x{item['count']}): ${item['price']:.2f}")
        lines.append(f"Total: ${self.calculate_total():.2f}")
        self._buffer = "\n".join(lines)

    def read(self, __n=-1):
        """Generates a dynamic receipt string and returns a slice of it."""
        if not self._is_closed:
            self.flush()

        if __n == -1:
            result = self._buffer[self._cursor:]
            self._cursor = len(self._buffer)
            return result
        else:
            result = self._buffer[self._cursor : self._cursor + __n]
            self._cursor += len(result)
            return result

    def checkout(self):
        """Finalizes the order and returns the final transaction amount."""
        if not self._is_closed:
            self.flush()
            self._is_closed = True
        return self.calculate_total()

    def close(self):
        """Closes the virtual stream and triggers checkout."""
        if not self._is_closed:
            self.checkout()

    def closed(self):
        """Checks if the order session is finalized."""
        return self._is_closed

    def seek(self, __offset, __whence=0):
        """Moves the internal read cursor within the generated receipt buffer."""
        if __whence == 0:   # SEEK_SET
            self._cursor = __offset
        elif __whence == 1: # SEEK_CUR
            self._cursor += __offset
        elif __whence == 2: # SEEK_END
            self._cursor = len(self._buffer) + __offset

        # Ensure cursor is not negative
        if self._cursor < 0:
            self._cursor = 0
        return self._cursor

    def tell(self):
        """Returns the current position of the cursor."""
        return self._cursor

    def flush(self):
        """Synchronizes the internal buffer with the current state."""
        self._update_buffer()

    def writable(self):
        """Checks if items can still be added to the order."""
        return not self._is_closed

    def readable(self):
        """Checks if the receipt can be generated/read."""
        return True

    def __iter__(self):
        """Allows iteration over lines in the generated receipt."""
        return self

    def __next__(self):
        """Returns the next line of the receipt."""
        if self._cursor >= len(self._buffer):
            raise StopIteration

        try:
            # Find the next newline character
            newline_pos = self._buffer.index('\n', self._cursor)
            line = self._buffer[self._cursor : newline_pos + 1]
            self._cursor = newline_pos + 1
            return line
        except ValueError:
            # No newline found, return the rest of the buffer
            line = self._buffer[self._cursor:]
            self._cursor = len(self._buffer)
            return line

    def __enter__(self):
        """Context manager entry."""
        return self

    def __exit__(self, __t, __value, __traceback):
        """Context manager exit. Automatically calls close()."""
        self.close()

    def fileno(self):
        """Satisfies file interface."""
        return -1

    def isatty(self):
        """Checks if connected to a terminal."""
        return False
